<template>
  <div class="ap-root ap-root--error" v-if="loadError">
    <v-alert type="error" outlined prominent border="left" class="ma-6">
      {{ loadError }}
    </v-alert>
  </div>
  <div class="ap-root" v-else-if="!loading">
    <!-- ── POSITION PICKER DIALOG ──────────────────────────────────────── -->
    <v-dialog v-model="positionDialog" max-width="960" scrollable>
      <v-card class="ap-dialog">
        <div class="ap-dialog__strip ap-dialog__strip--blue"></div>
        <v-card-title class="ap-dialog__head">
          <div
            class="ap-dialog__icon"
            style="background:linear-gradient(135deg,#1e40af,#3b82f6)"
          >
            <v-icon color="white" size="18">mdi-briefcase-search</v-icon>
          </div>
          <div class="ml-3">
            <div class="ap-dialog__title">Select Position</div>
            <div class="ap-dialog__sub">
              Browse and select an available position
            </div>
          </div>
          <v-spacer />
          <v-btn icon small @click="positionDialog = false">
            <v-icon color="#a8a29e">mdi-close</v-icon>
          </v-btn>
        </v-card-title>

        <v-card-text class="ap-dialog__filters">
          <v-row dense>
            <v-col cols="12" sm="6">
              <v-text-field
                v-model="posFilter.designation"
                label="Search Designation"
                dense
                outlined
                clearable
                hide-details
                prepend-inner-icon="mdi-magnify"
                @input="debouncedFetchPositions"
              />
            </v-col>
            <v-col cols="12" sm="6">
              <v-autocomplete
                v-model="posFilter.department"
                :items="departmentOptions"
                item-text="display"
                item-value="code"
                label="Department"
                dense
                outlined
                clearable
                hide-details
                @change="fetchPositions"
              />
            </v-col>
            <v-col cols="12">
              <v-menu
                v-model="posFilterTreeOpen"
                :close-on-content-click="false"
                offset-y
                min-width="320px"
              >
                <template v-slot:activator="{ on }">
                  <v-text-field
                    :value="filterTree.displayValue"
                    label="Filter by Location"
                    dense
                    outlined
                    clearable
                    hide-details
                    readonly
                    prepend-inner-icon="mdi-map-marker-outline"
                    v-on="on"
                    @click:clear="clearFilterTree"
                  />
                </template>
                <v-card class="ap-tree-card">
                  <v-treeview
                    :active.sync="filterTree.active"
                    :items="filterTree.items"
                    :load-children="fetchFilterChildren"
                    :open.sync="filterTree.open"
                    activatable
                    :multiple-active="false"
                    selection-type="independent"
                    :loading="filterTree.loading"
                    item-key="id"
                    dense
                    hoverable
                    open-on-click
                  >
                    <template v-slot:label="{ item }">
                      <span class="ap-tree-label">{{ item.name }}</span>
                    </template>
                  </v-treeview>
                </v-card>
              </v-menu>
            </v-col>
          </v-row>
        </v-card-text>

        <v-card-text class="pa-0">
          <v-data-table
            :headers="positionHeaders"
            :items="positionItems"
            :loading="loadingPositions"
            :server-items-length="positionTotal"
            :options.sync="positionOptions"
            :footer-props="{ 'items-per-page-options': [10, 20, 50] }"
            item-key="id"
            class="ap-picker-table"
            :item-class="(item) => (item.vacant <= 0 ? 'ap-row-full' : '')"
            @click:row="
              (item) =>
                item.vacant > 0 &&
                item.statusCode === 'active' &&
                selectPosition(item)
            "
          >
            <template v-slot:item.designation="{ item }">
              <span class="ap-table-bold">{{ item.designation }}</span>
            </template>
            <template v-slot:item.grade="{ item }">
              <v-chip
                x-small
                label
                color="indigo lighten-5"
                text-color="indigo darken-2"
              >
                {{ item.grade || "—" }}
              </v-chip>
            </template>
            <template v-slot:item.vacant="{ item }">
              <div class="ap-vacant-cell">
                <v-chip
                  x-small
                  label
                  :color="item.vacant > 0 ? 'green lighten-5' : 'red lighten-5'"
                  :text-color="
                    item.vacant > 0 ? 'green darken-2' : 'red darken-2'
                  "
                >
                  {{ item.vacant }} / {{ item.maxPosts }}
                </v-chip>
                <div class="ap-vacant-bar">
                  <div
                    class="ap-vacant-bar__fill"
                    :style="{
                      width: item.maxPosts
                        ? (item.filled / item.maxPosts) * 100 + '%'
                        : '0%',
                      background: item.vacant > 0 ? '#22c55e' : '#ef4444',
                    }"
                  ></div>
                </div>
              </div>
            </template>
            <template v-slot:item._action="{ item }">
              <v-btn
                x-small
                depressed
                color="primary"
                :disabled="item.vacant <= 0"
                :title="
                  item.vacant <= 0
                    ? 'No vacant posts available'
                    : 'Select this position'
                "
                @click.stop="selectPosition(item)"
              >
                Select <v-icon right x-small>mdi-check</v-icon>
              </v-btn>
            </template>
          </v-data-table>
        </v-card-text>
      </v-card>
    </v-dialog>

    <!-- ── SUPERVISOR PICKER DIALOG ────────────────────────────────────── -->
    <v-dialog v-model="supervisorDialog" max-width="960" scrollable>
      <v-card class="ap-dialog">
        <div class="ap-dialog__strip ap-dialog__strip--purple"></div>
        <v-card-title class="ap-dialog__head">
          <div
            class="ap-dialog__icon"
            style="background:linear-gradient(135deg,#6d28d9,#8b5cf6)"
          >
            <v-icon color="white" size="18">mdi-account-tie</v-icon>
          </div>
          <div class="ml-3">
            <div class="ap-dialog__title">Select Supervisor</div>
            <div class="ap-dialog__sub">
              Choose from currently active staff members
            </div>
          </div>
          <v-spacer />
          <v-btn icon small @click="supervisorDialog = false">
            <v-icon color="#a8a29e">mdi-close</v-icon>
          </v-btn>
        </v-card-title>

        <v-card-text class="ap-dialog__filters">
          <v-row dense>
            <v-col cols="12" sm="4">
              <v-text-field
                v-model="supFilter.name"
                label="Search by Name"
                dense
                outlined
                clearable
                hide-details
                prepend-inner-icon="mdi-magnify"
                @input="debouncedFetchSupervisors"
              />
            </v-col>
            <v-col cols="12" sm="4">
              <v-text-field
                v-model="supFilter.position"
                label="Position / Designation"
                dense
                outlined
                clearable
                hide-details
                prepend-inner-icon="mdi-briefcase-outline"
                @input="debouncedFetchSupervisors"
              />
            </v-col>
            <v-col cols="12" sm="4">
              <v-autocomplete
                v-model="supFilter.department"
                :items="departmentOptions"
                item-text="display"
                item-value="code"
                label="Department"
                dense
                outlined
                clearable
                hide-details
                @change="fetchSupervisors"
              />
            </v-col>
            <v-col cols="12">
              <v-menu
                v-model="supFilterTreeOpen"
                :close-on-content-click="false"
                offset-y
                min-width="320px"
              >
                <template v-slot:activator="{ on }">
                  <v-text-field
                    :value="filterTree.displayValue"
                    label="Filter by Location"
                    dense
                    outlined
                    clearable
                    hide-details
                    readonly
                    prepend-inner-icon="mdi-map-marker-outline"
                    v-on="on"
                    @click:clear="clearFilterTree"
                  />
                </template>
                <v-card class="ap-tree-card">
                  <v-treeview
                    :active.sync="filterTree.active"
                    :items="filterTree.items"
                    :load-children="fetchFilterChildren"
                    :open.sync="filterTree.open"
                    activatable
                    :multiple-active="false"
                    selection-type="independent"
                    :loading="filterTree.loading"
                    item-key="id"
                    dense
                    hoverable
                    open-on-click
                  >
                    <template v-slot:label="{ item }">
                      <span class="ap-tree-label">{{ item.name }}</span>
                    </template>
                  </v-treeview>
                </v-card>
              </v-menu>
            </v-col>
          </v-row>
        </v-card-text>

        <v-card-text class="pa-0">
          <v-data-table
            :headers="supervisorHeaders"
            :items="supervisorItems"
            :loading="loadingSupervisors"
            :server-items-length="supervisorTotal"
            :options.sync="supervisorOptions"
            :footer-props="{ 'items-per-page-options': [10, 20, 50] }"
            item-key="id"
            class="ap-picker-table"
            @click:row="selectSupervisor"
          >
            <template v-slot:item.name="{ item }">
              <div class="ap-sup-name-cell">
                <v-avatar size="28" color="purple lighten-4" class="mr-2">
                  <span class="ap-initials indigo--text text--darken-3">{{
                    getInitials(item.name)
                  }}</span>
                </v-avatar>
                <div>
                  <div class="ap-table-bold">{{ item.name }}</div>
                  <v-chip
                    v-if="item.isHOD"
                    x-small
                    color="amber lighten-4"
                    text-color="amber darken-4"
                    class="mt-1"
                  >
                    <v-icon x-small left>mdi-account-star</v-icon>HOD
                  </v-chip>
                </div>
              </div>
            </template>
            <template v-slot:item.grade="{ item }">
              <v-chip
                v-if="item.grade"
                x-small
                label
                color="teal lighten-5"
                text-color="teal darken-2"
              >
                {{ item.grade }}
              </v-chip>
              <span v-else class="ap-muted">—</span>
            </template>
            <template v-slot:item.employmentCategory="{ item }">
              <v-chip
                v-if="item.employmentCategory"
                x-small
                label
                color="blue-grey lighten-5"
                text-color="blue-grey darken-2"
              >
                {{ item.employmentCategory }}
              </v-chip>
              <span v-else class="ap-muted">—</span>
            </template>
            <template v-slot:item._action="{ item }">
              <v-btn
                x-small
                depressed
                color="primary"
                @click.stop="selectSupervisor(item)"
              >
                Select <v-icon right x-small>mdi-check</v-icon>
              </v-btn>
            </template>
          </v-data-table>
        </v-card-text>
      </v-card>
    </v-dialog>

    <v-form ref="form" v-model="formValid" lazy-validation>
      <div class="pv-hero">
        <div class="pv-hero__left">
          <div class="pv-hero__avatar">
            <span>{{ initials }}</span>
          </div>
          <div>
            <div class="pv-hero__name">{{ heroTitle }}</div>
            <div v-if="heroSubtitle" class="pv-hero__subtitle">
              {{ heroSubtitle }}
            </div>
          </div>
        </div>
        <div class="pv-hero__badges">
          <div
            v-if="isPromotion"
            class="pv-hero__mode-badge pv-hero__mode-badge--promo"
          >
            <v-icon size="13" color="#92400e">mdi-arrow-up-circle</v-icon>
            Promotion
          </div>
          <div
            v-if="isTermination"
            class="pv-hero__mode-badge pv-hero__mode-badge--term"
          >
            <v-icon size="13" color="#991b1b">mdi-close-circle</v-icon>
            Termination
          </div>
        </div>
      </div>
      <v-navigation-drawer
        app
        class="primary darken-1 white--text"
        clipped
        permanent
        right
        style="z-index: 3;"
      >
        <v-list class="white--text">
          <v-list-item>
            <v-btn class="secondary" dark @click="$router.go(-1)">
              <v-icon light>mdi-close-circle-outline</v-icon>
              <span>{{ $t("App.hardcoded-texts.Cancel") }}</span>
            </v-btn>
            <v-spacer></v-spacer>
            <v-btn
              v-if="formValid"
              :disabled="!formValid || saving"
              class="success darken-1"
              dark
              @click="submit"
            >
              <v-icon light>mdi-content-save</v-icon>
              <span>{{ $t("App.hardcoded-texts.Save") }}</span>
            </v-btn>
            <v-btn v-else class="green" dark @click="submit" :disabled="saving">
              <v-icon light>mdi-content-save</v-icon>
              <span>{{ $t("App.hardcoded-texts.Save") }}</span>
            </v-btn>
          </v-list-item>
          <v-divider color="white"></v-divider>
        </v-list>
      </v-navigation-drawer>
      <!-- ── CURRENT POSITION (read-only, promotion + termination) ─── -->
      <div
        v-if="isPromotion || isTermination"
        class="ap-section ap-section--prev"
      >
        <div
          class="ap-section__header"
          :style="
            isPromotion
              ? 'background:linear-gradient(135deg,#78350f 0%,#b45309 100%)'
              : 'background:linear-gradient(135deg,#7f1d1d 0%,#b91c1c 100%)'
          "
        >
          <span class="ap-section__num">↓</span>
          <div>
            <div class="ap-section__title">
              {{ isPromotion ? "Current Position" : "Position Being Closed" }}
            </div>
            <div class="ap-section__sub">
              {{
                isPromotion
                  ? "This position will be closed when the new one is saved"
                  : "This is the position that will be terminated"
              }}
            </div>
          </div>
          <v-spacer />
          <div v-if="currentRole.designation" class="ap-section__badge-live">
            <v-icon size="10" color="#86efac">mdi-check-circle</v-icon>
            Active
          </div>
        </div>
        <div class="ap-section__body">
          <v-row dense>
            <v-col cols="12" sm="6" md="4">
              <div class="ap-prev-field">
                <div class="ap-prev-field__label">
                  <v-icon size="11" color="#a8a29e" class="mr-1"
                    >mdi-briefcase-outline</v-icon
                  >
                  Designation
                </div>
                <div class="ap-prev-field__value">
                  {{ currentRole.designation || "—" }}
                </div>
              </div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="ap-prev-field">
                <div class="ap-prev-field__label">
                  <v-icon size="11" color="#a8a29e" class="mr-1"
                    >mdi-tag-outline</v-icon
                  >
                  Department
                </div>
                <div class="ap-prev-field__value">
                  {{ currentRole.department || "—" }}
                </div>
              </div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="ap-prev-field">
                <div class="ap-prev-field__label">
                  <v-icon size="11" color="#a8a29e" class="mr-1"
                    >mdi-hospital-building</v-icon
                  >
                  Facility
                </div>
                <div class="ap-prev-field__value ap-prev-field__value--strong">
                  {{ currentRole.facility || "—" }}
                </div>
              </div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="ap-prev-field">
                <div class="ap-prev-field__label">
                  <v-icon size="11" color="#a8a29e" class="mr-1"
                    >mdi-account-hard-hat</v-icon
                  >
                  Employment Category
                </div>
                <div class="ap-prev-field__value">
                  <v-chip
                    x-small
                    label
                    color="blue-grey lighten-5"
                    text-color="blue-grey darken-2"
                  >
                    {{ currentRole.employmentCategory || "—" }}
                  </v-chip>
                </div>
              </div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="ap-prev-field">
                <div class="ap-prev-field__label">
                  <v-icon size="11" color="#a8a29e" class="mr-1"
                    >mdi-calendar-range</v-icon
                  >
                  Period
                </div>
                <div class="ap-prev-field__value ap-prev-field__value--mono">
                  {{ currentRole.startDate || "—" }}
                  <v-icon size="10" color="#a8a29e">mdi-arrow-right</v-icon>
                  {{ currentRole.endDate || "Present" }}
                </div>
              </div>
            </v-col>
            <v-col cols="12" sm="6" md="4" v-if="currentRole.supervisor">
              <div class="ap-prev-field">
                <div class="ap-prev-field__label">
                  <v-icon size="11" color="#a8a29e" class="mr-1"
                    >mdi-account-tie</v-icon
                  >
                  Supervisor
                </div>
                <div class="ap-prev-field__value ap-prev-field__value--strong">
                  {{ currentRole.supervisor }}
                </div>
              </div>
            </v-col>
            <v-col cols="12" sm="6" md="4" v-if="currentRole.isHOD">
              <div class="ap-prev-field">
                <div class="ap-prev-field__label">
                  <v-icon size="11" color="#a8a29e" class="mr-1"
                    >mdi-account-star</v-icon
                  >
                  HOD
                </div>
                <div class="ap-prev-field__value">
                  <v-chip
                    x-small
                    label
                    color="amber lighten-4"
                    text-color="amber darken-4"
                  >
                    {{
                      currentRole.hodType
                        ? currentRole.hodType.charAt(0).toUpperCase() +
                          currentRole.hodType.slice(1)
                        : "Yes"
                    }}
                  </v-chip>
                </div>
              </div>
            </v-col>
            <v-col
              cols="12"
              sm="6"
              md="4"
              v-if="currentRole.isDepartmentalDirector"
            >
              <div class="ap-prev-field">
                <div class="ap-prev-field__label">
                  <v-icon size="11" color="#a8a29e" class="mr-1"
                    >mdi-account-tie</v-icon
                  >
                  Departmental Director
                </div>
                <div class="ap-prev-field__value">
                  <v-chip
                    x-small
                    label
                    color="indigo lighten-4"
                    text-color="indigo darken-4"
                  >
                    Yes
                  </v-chip>
                </div>
              </div>
            </v-col>
          </v-row>
        </div>
      </div>

      <!-- ── PROMOTION label divider ──────────────────────────────────── -->
      <div v-if="isPromotion" class="ap-transition-divider">
        <div class="ap-transition-divider__line"></div>
        <div class="ap-transition-divider__pill">
          <v-icon size="14" color="#1e40af">mdi-arrow-down-circle</v-icon>
          New Position
        </div>
        <div class="ap-transition-divider__line"></div>
      </div>

      <!-- ── TERMINATION FORM (only shown in termination mode) ──────── -->
      <template v-if="isTermination">
        <!-- Section T-01: Termination Details -->
        <div class="ap-section">
          <div
            class="ap-section__header"
            style="background:linear-gradient(135deg,#7f1d1d 0%,#b91c1c 100%)"
          >
            <span class="ap-section__num">01</span>
            <div>
              <div class="ap-section__title">Termination Details</div>
              <div class="ap-section__sub">
                Record the reason and effective date for ending this position
              </div>
            </div>
          </div>
          <div class="ap-section__body">
            <v-row>
              <!-- Last Working Date -->
              <v-col cols="12" sm="6">
                <v-menu
                  v-model="departureDateMenu"
                  :close-on-content-click="false"
                  max-width="290px"
                  min-width="290px"
                >
                  <template v-slot:activator="{ on, attrs }">
                    <v-text-field
                      :value="departure.lastWorkingDate"
                      label="Last Working Date"
                      outlined
                      dense
                      readonly
                      :rules="[rules.required]"
                      prepend-inner-icon="mdi-calendar-remove"
                      v-bind="attrs"
                      v-on="on"
                    />
                  </template>
                  <v-date-picker
                    v-model="departure.lastWorkingDate"
                    no-title
                    @input="departureDateMenu = false"
                  />
                </v-menu>
              </v-col>

              <!-- Reason for Termination -->
              <v-col cols="12" sm="6">
                <v-select
                  v-model="departure.reason"
                  :items="departureReasonOptions"
                  item-text="display"
                  :rules="[rules.required]"
                  label="Reason for Termination"
                  outlined
                  dense
                  return-object
                  clearable
                  prepend-inner-icon="mdi-file-document-remove-outline"
                  @change="
                    departure.dismissalReason = '';
                    departure.resignationReasons = [];
                    departure.resignationReasonOther = '';
                    clearDepartureTransferTree();
                  "
                />
              </v-col>

              <!-- Conditional: Dismissal reason -->
              <v-col cols="12" sm="6" v-if="showDismissalField">
                <v-text-field
                  v-model="departure.dismissalReason"
                  label="Reason for Dismissal"
                  outlined
                  dense
                  :rules="[rules.required]"
                  prepend-inner-icon="mdi-gavel"
                />
              </v-col>

              <!-- Conditional: Resignation details -->
              <template v-if="showResignationDetails">
                <v-col cols="12" sm="6">
                  <v-autocomplete
                    v-model="departure.resignationReasons"
                    :items="resignationReasonOptions"
                    item-text="display"
                    :rules="[
                      (v) =>
                        (v && v.length > 0) || 'At least one reason required',
                    ]"
                    label="Resignation Reasons"
                    outlined
                    dense
                    multiple
                    return-object
                    chips
                    small-chips
                    deletable-chips
                    prepend-inner-icon="mdi-clipboard-text-outline"
                  />
                </v-col>
                <v-col cols="12" sm="6" v-if="showResignationOther">
                  <v-text-field
                    v-model="departure.resignationReasonOther"
                    label="Other Resignation Reason"
                    outlined
                    dense
                    prepend-inner-icon="mdi-pencil-outline"
                  />
                </v-col>
              </template>

              <!-- Conditional: Transfer-out facility -->
              <v-col cols="12" sm="6" v-if="showTransferOutDetails">
                <v-menu
                  v-model="departureTransferTreeOpen"
                  :close-on-content-click="false"
                  offset-y
                  min-width="320px"
                  @input="
                    (val) => {
                      if (val) loadDepartureTransferTree();
                    }
                  "
                >
                  <template v-slot:activator="{ on }">
                    <v-text-field
                      :value="departureTransferTree.displayValue"
                      label="Transfer To Facility"
                      dense
                      outlined
                      clearable
                      hide-details
                      readonly
                      prepend-inner-icon="mdi-hospital-building"
                      v-on="on"
                      @click:clear="clearDepartureTransferTree"
                    />
                  </template>
                  <v-card class="ap-tree-card">
                    <v-treeview
                      :active.sync="departureTransferTree.active"
                      :items="departureTransferTree.items"
                      :load-children="fetchDepartureTransferChildren"
                      :open.sync="departureTransferTree.open"
                      activatable
                      :multiple-active="false"
                      selection-type="independent"
                      :loading="departureTransferTree.loading"
                      item-key="id"
                      dense
                      hoverable
                      open-on-click
                      @update:active="onDepartureTransferTreeActiveChange"
                    >
                      <template v-slot:label="{ item }">
                        <span class="ap-tree-label">{{ item.name }}</span>
                      </template>
                    </v-treeview>
                  </v-card>
                </v-menu>
                <div
                  v-if="
                    formSubmitted &&
                      showTransferOutDetails &&
                      !departure.transferToFacility.reference
