      // Departure ValueSet options
      departureReasonOptions: [],
      resignationReasonOptions: [],

      rules: {
        required: (v) => !!v || "This field is required",
      },
    };
  },

  computed: {
    isEdit() {
      return !!this.queries.role && !this.isPromotion && !this.isTermination;
    },
    isPromotion() {
      return this.queries.type === "promotion";
    },
    isTermination() {
      return this.queries.type === "termination";
    },
    heroTitle() {
      if (this.isPromotion)
        return `Position Change / Promotion — ${this.practitionerName}`;
      if (this.isTermination)
        return `Contract Termination — ${this.practitionerName}`;
      return `Position Management for ${this.practitionerName}`;
    },
    heroSubtitle() {
      if (this.isPromotion)
        return "Closing current position and assigning a new one";
      if (this.isTermination)
        return "Recording reason for ending this position";
      return null;
    },
    // Departure conditional field visibility
    showDismissalField() {
      return this.departure.reason?.code === "dismissal";
    },
    showResignationDetails() {
      return this.departure.reason?.code === "resignation";
    },
    showTransferOutDetails() {
      return this.departure.reason?.code === "transferout";
    },
    showResignationOther() {
      return this.departure.resignationReasons?.some((r) => r.code === "other");
    },
    initials() {
      return this.getInitials(this.practitionerName);
    },
    isPermanent() {
      const code = (this.form.employmentCategory?.code || "").toLowerCase();
      const disp = (this.form.employmentCategory?.display || "").toLowerCase();
      return code.includes("permanent") || disp.includes("permanent");
    },
    hodSummary() {
      if (this.form.isHeadOfDepartment?.code !== "yes") return null;
      const dept = this.form.position.department;
      if (!dept || !this.hodTree.active.length) return null;
      const id = this.hodTree.active[0];
      const info = this.hodTree.treeLookup[id];
      if (!info) return null;
      if (this.form.hodType === "district") {
        return `This staff will be Head of ${dept} Department at ${info.name} District`;
      }
      if (this.form.hodType === "facility" && info.type === "facility") {
        return `This staff will be Head of ${dept} Department at ${info.name}`;
      }
      return null;
    },
  },

  watch: {
    isPermanent(val) {
      if (val) this.form.endDate = null;
    },
    "filterTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      this.filterTree.displayValue = id
        ? this.filterTree.treeLookup[id]?.name || id
        : "";
      this.fetchPositions();
      this.fetchSupervisors();
    },
    "hodTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      this.hodTree.displayValue = id
        ? this.hodTree.treeLookup[id]?.name || id
        : "";
    },
    positionOptions: {
      handler() {
        if (this.positionDialog) this.fetchPositions();
      },
      deep: true,
    },
    supervisorOptions: {
      handler() {
        if (this.supervisorDialog) this.fetchSupervisors();
      },
      deep: true,
    },
    "salaryTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      if (!id) {
        this.salaryTree.displayValue = "";
        this.form.salaryNotch = null;
        return;
      }
      const info = this.salaryTree.treeLookup[id];
      if (!info || info.type !== "notch") return;
      const display = info.gradeDisplay
        ? `${info.gradeDisplay}  /  ${info.name} (${info.amount})`
        : info.name;
      this.salaryTree.displayValue = display;
      this.form.salaryNotch = { reference: id, display };
      this.salaryTreeOpen = false;
    },
  },

  async mounted() {
    //if (
    // !this.$store.state?.user?.obj?.permissions?.special?.special?.id?.[
    // "set-position"
    // ]
    //) {
    //}
    this.loading = true;
    const baseTasks = [this.loadValueSets(), this.loadFilterTree()];
    if (!this.isTermination) baseTasks.push(this.loadSalaryGrades());
    if (this.isTermination) baseTasks.push(this.loadDepartureValueSets());
    await Promise.all(baseTasks);

    if (this.isPromotion || this.isTermination) {
      await this.loadCurrentRole();
    } else if (this.isEdit) {
      await this.loadExistingRole();
    } else {
      await this.checkNoExistingRole();
    }
    if (!this.loadError) await this.loadPractitioner();
    this.loading = false;
  },

  methods: {
    async loadPractitioner() {
      try {
        const res = await fetch(
          `/fhir/Practitioner/${this.queries.practitioner}`,
        );
        const data = await res.json();
        this.practitionerName = this.parsePractitionerName(data);
      } catch (_) {
        this.practitionerName = `Practitioner/${this.queries.practitioner}`;
      }
    },

    parsePractitionerName(resource) {
      if (!resource?.name?.length) return "";
      const nameObj = resource.name[0];
      const given = nameObj.given ? nameObj.given.join(" ") : "";
      const family = nameObj.family || "";
      return (given + " " + family).trim();
    },
    // ── ValueSets ──────────────────────────────────────────────────────
    async loadValueSets() {
      const [empCat, yesNo, offerType, dept] = await Promise.all([
        this.$fhirutils.expand(VS.EMP_CAT),
        this.$fhirutils.expand(VS.YES_NO),
        this.$fhirutils.expand(VS.OFFER_TYPE),
        this.$fhirutils.expand(VS.DEPARTMENT),
      ]);
      this.employmentCategoryOptions = this.parseExpansion(empCat);
      this.yesNoOptions = this.parseExpansion(yesNo);
      this.offerTypeOptions = this.parseExpansion(offerType);
      this.departmentOptions = this.parseExpansion(dept);
    },

    parseExpansion(vs) {
      return (vs || []).map((c) => ({
        system: c.system,
        code: c.code,
        display: c.display,
      }));
    },

    // ── Position picker ────────────────────────────────────────────────
    openPositionDialog() {
      this.positionDialog = true;
      this.fetchPositions();
    },

    debouncedFetchPositions() {
      clearTimeout(this.posDebounce);
      this.posDebounce = setTimeout(() => {
        this.positionOptions.page = 1;
        this.fetchPositions();
      }, 350);
    },

    async fetchPositions() {
      this.loadingPositions = true;
      try {
        const params = new URLSearchParams({
          page: this.positionOptions.page,
          count: this.positionOptions.itemsPerPage,
        });
        if (this.posFilter.designation)
          params.set("designation", this.posFilter.designation);
        if (this.posFilter.department)
          params.set("department", this.posFilter.department);
        if (this.filterTree.active.length) {
          const id = this.filterTree.active[0];
          const info = this.filterTree.treeLookup[id];
          const locationId = id.split("/")[1];
          if (info?.type === "facility") params.set("facilityId", locationId);
          else if (info?.type === "council")
            params.set("councilId", locationId);
          else params.set("districtId", locationId);
        }

        const res = await fetch(`/site/position/report?${params}`);
        const data = await res.json();

        this.positionTotal = data.total || 0;
        this.positionItems = data.positions || [];
      } catch (err) {
        console.error("fetchPositions error", err);
      } finally {
        this.loadingPositions = false;
      }
    },

    selectPosition(item) {
      this.form.position = {
        reference: item.reference,
        display: item.designation || item.display,
        facility: item.facility,
        department: item.department,
      };
      this.positionDialog = false;
    },

    clearPosition() {
      this.form.position = {
        reference: null,
        display: "",
        facility: "",
        department: "",
      };
    },

    // ── Supervisor picker ──────────────────────────────────────────────
    openSupervisorDialog() {
      this.supervisorDialog = true;
      this.fetchSupervisors();
    },

    debouncedFetchSupervisors() {
      clearTimeout(this.supDebounce);
      this.supDebounce = setTimeout(() => {
        this.supervisorOptions.page = 1;
        this.fetchSupervisors();
      }, 350);
    },

    async fetchSupervisors() {
      this.loadingSupervisors = true;
      try {
        const params = new URLSearchParams({
          page: this.supervisorOptions.page,
          count: this.supervisorOptions.itemsPerPage,
        });
        if (this.supFilter.name) params.set("name", this.supFilter.name);
        if (this.supFilter.position)
          params.set("position", this.supFilter.position);
        if (this.supFilter.department)
          params.set("department", this.supFilter.department);
        if (this.filterTree.active.length) {
          const id = this.filterTree.active[0];
          const info = this.filterTree.treeLookup[id];
          const locationId = id.split("/")[1];
          if (info?.type === "facility") params.set("facilityId", locationId);
          else if (info?.type === "council")
            params.set("councilId", locationId);
          else params.set("districtId", locationId);
        }

        const res = await fetch(`/site/position/supervisors?${params}`);
        const data = await res.json();

        this.supervisorTotal = data.total || 0;
        this.supervisorItems = data.supervisors || [];
      } catch (err) {
        console.error("fetchSupervisors error", err);
      } finally {
        this.loadingSupervisors = false;
      }
    },

    selectSupervisor(item) {
      this.form.supervisor = {
        reference: item.practitionerRef,
        display: item.name,
        position: item.position,
        facility: item.facility,
        grade: item.grade,
      };
      this.supervisorDialog = false;
    },

    clearSupervisor() {
      this.form.supervisor = {
        reference: null,
        display: "",
        position: "",
        facility: "",
        grade: "",
      };
    },

    // ── HOD handlers ───────────────────────────────────────────────────
    onHodChange() {
      if (this.form.isHeadOfDepartment?.code !== "yes") {
        this.form.hodType = null;
        this.clearHodTree();
      } else {
        this.loadHodTree();
      }
    },

    onHodTypeChange() {
      this.clearHodTree();
      this.loadHodTree();
    },

    // ── HOD treeview ───────────────────────────────────────────────────
    async loadHodTree() {
      if (!this.form.hodType) return;
      this.hodTree.loading = true;
      this.hodTree.items = [];
      this.hodTree.treeLookup = {};
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const facilityMode = this.form.hodType === "facility";
        const nodes = (data.entry || []).map((e) => {
          const node = {
            id: "Location/" + e.resource.id,
            name: e.resource.name,
            locked: facilityMode, // districts not selectable in facility mode
          };
          if (facilityMode) node.children = []; // lazy-loadable in facility mode
          this.hodTree.treeLookup[node.id] = {
            name: node.name,
            type: "district",
          };
          return node;
        });
        this.hodTree.items = nodes;
      } catch (err) {
        console.error("loadHodTree error", err);
      } finally {
        this.hodTree.loading = false;
      }
    },

    fetchHodChildren(item) {
      // Called by v-treeview when expanding a node with children: []
      const parentInfo = this.hodTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      return fetch(`/fhir/Location?partof=${item.id}&_count=200`)
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const node = {
              id: "Location/" + e.resource.id,
              name: e.resource.name,
              locked: childType !== "facility", // only facilities are selectable
            };
            if (childType === "council") node.children = []; // councils expand further
            this.hodTree.treeLookup[node.id] = {
              name: node.name,
              type: childType,
            };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) => console.error("fetchHodChildren error", err));
    },

    clearHodTree() {
      this.hodTree.active = [];
      this.hodTree.open = [];
      this.hodTree.displayValue = "";
      this.hodTree.items = [];
      this.hodTree.treeLookup = {};
    },

    // ── Filter treeview (shared across picker dialogs) ─────────────────
    async loadFilterTree() {
      if (this.filterTree.items.length) return;
      this.filterTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => ({
          id: "Location/" + e.resource.id,
          name: e.resource.name,
          children: [], // lazy-loadable
        }));
        nodes.forEach((n) => {
          this.filterTree.treeLookup[n.id] = { name: n.name, type: "district" };
        });
        this.filterTree.items = nodes;
      } catch (err) {
        console.error("loadFilterTree error", err);
      } finally {
        this.filterTree.loading = false;
      }
    },

    fetchFilterChildren(item) {
      // Called by v-treeview when expanding a node with children: []
      // Districts load councils; councils load facilities (leaf nodes)
      const parentInfo = this.filterTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      return fetch(`/fhir/Location?partof=${item.id}&_count=200`)
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const node = {
              id: "Location/" + e.resource.id,
              name: e.resource.name,
            };
            if (childType === "council") node.children = []; // councils expand to facilities
            this.filterTree.treeLookup[node.id] = {
              name: node.name,
              type: childType,
            };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) => console.error("fetchFilterChildren error", err));
    },

    clearFilterTree() {
      this.filterTree.active = [];
      this.filterTree.displayValue = "";
    },

    // ── Salary notch treeview ──────────────────────────────────────────
    async loadSalaryGrades() {
      if (this.salaryTree.items.length) return;
      this.salaryTree.loading = true;
      try {
        const res = await fetch(
          `/fhir/Basic?_profile=${GRADE_PROFILE}&_count=200&_sort=name`,
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => {
          const gradeName =
            this.getExt(e.resource, EXT.POS_NAME, "valueString") ||
            e.resource.id;
          const id = `Basic/${e.resource.id}`;
          this.salaryTree.treeLookup[id] = {
            name: gradeName,
            type: "grade",
          };
          return {
            id,
            name: gradeName,
            type: "grade",
            locked: true, // grades are not selectable — only notches are
            children: [], // lazy: expanded by v-treeview via fetchSalaryNotchChildren
          };
        });
        this.salaryTree.items = nodes;
      } catch (err) {
        console.error("loadSalaryGrades error", err);
      } finally {
        this.salaryTree.loading = false;
      }
    },

    fetchSalaryNotchChildren(gradeNode) {
      // Called by v-treeview when expanding a grade node.
      // Fetches all notches that reference this grade.
      const gradeId = gradeNode.id.split("/")[1];
      const gradeDisplay = this.salaryTree.treeLookup[gradeNode.id]?.name || "";
      return fetch(
        `/fhir/Basic?_profile=${NOTCH_PROFILE}&salarygrade=Basic/${gradeId}&_count=200`,
      )
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const notchCoding = this.getExt(
              e.resource,
              EXT.NOTCH,
              "valueCoding",
            );
            const amountExt = e.resource.extension?.find(
              (x) => x.url === EXT.SALARY_AMOUNT,
            );
            const money = amountExt?.valueMoney;
            const amount = money
              ? `${money.currency} ${Number(money.value).toLocaleString()}`
              : "";
            const notchName = notchCoding
              ? notchCoding.display || notchCoding.code
              : e.resource.id;
            const id = `Basic/${e.resource.id}`;
            this.salaryTree.treeLookup[id] = {
              name: notchName,
              gradeDisplay,
              amount,
              type: "notch",
            };
            return { id, name: notchName, amount, type: "notch" };
          });
          gradeNode.children.push(...children);
        })
        .catch((err) => console.error("fetchSalaryNotchChildren error", err));
    },

    clearSalaryTree() {
      this.salaryTree.active = [];
      this.salaryTree.open = [];
      this.salaryTree.displayValue = "";
      this.form.salaryNotch = null;
    },

    // ── Load existing role for edit ────────────────────────────────────
    async loadExistingRole() {
      try {
        const res = await fetch(`/fhir/PractitionerRole/${this.queries.role}`);
        const role = await res.json();
        if (role.active !== true) {
          this.loadError =
            "This position record has already ended and can no longer be edited.";
          return;
        }
        this.fhirId = this.queries.role;

        const posRef = this.getExt(role, EXT.POSITION, "valueReference");
        if (posRef) {
          this.form.position = {
            reference: posRef.reference,
            display: posRef.display || "",
            facility: "",
            department: "",
          };
          // Try to enrich with position details
          try {
            const posId = posRef.reference.split("/")[1];
            const posRes = await fetch(`/fhir/Basic/${posId}`);
            const posData = await posRes.json();
            this.form.position.display =
              posData.extension?.find((e) => {
                return (
                  e.url ===
                  "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
                );
              })?.valueString || this.form.position.display;
            this.form.position.department =
              posData.extension?.find((e) => {
                return (
                  e.url ===
                  "http://ihris.org/fhir/StructureDefinition/department"
                );
              })?.valueCoding?.display || "";
            this.form.position.facility =
              posData.extension?.find((e) => {
                return (
                  e.url === "http://ihris.org/fhir/StructureDefinition/facility"
                );
              })?.valueReference?.display || "";
          } catch (err) {
            console.log(err);
          }
        }

        const empCat = this.getExt(role, EXT.EMP_CAT, "valueCoding");
        if (empCat) this.form.employmentCategory = empCat;

        this.form.startDate = role.period?.start || null;
        this.form.endDate = role.period?.end || null;

        const offerType = this.getExt(role, EXT.OFFER_TYPE, "valueCoding");
        if (offerType) this.form.offerType = offerType;

        //Get supervisor data
        const supRef = this.getExt(role, EXT.SUPERVISOR, "valueReference");
        if (supRef?.reference) {
          let response = await fetch(
            "/fhir/PractitionerRole?practitioner=" +
              supRef.reference +
              "&_include=PractitionerRole:practitioner&_include=PractitionerRole:roleposition",
          );
          response = await response.json();
          let supervisorPract = response.entry.find(
            (entry) => entry.resource.resourceType === "Practitioner",
          )?.resource;
          // let supervisorRole = response.entry.find((entry) => entry.resource.resourceType === 'PractitionerRole')?.resource
          let supervisorPos = response.entry.find((entry) =>
            entry.resource.meta.profile.includes(
              "http://ihris.org/fhir/StructureDefinition/position-profile",
            ),
          )?.resource;
          let designationId = supervisorPos.extension
            ?.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/designation"
              );
            })
            ?.valueReference?.reference?.split("/")[1];
          if (designationId) {
            response = await fetch("/fhir/Basic/" + designationId);
            response = await response.json();
            this.form.supervisor.position =
              response?.extension?.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
                );
              })?.valueString || "";
          }

          let facilityId = supervisorPos.extension
            ?.find((ext) => {
              return (
                ext.url === "http://ihris.org/fhir/StructureDefinition/facility"
              );
            })
            ?.valueReference?.reference?.split("/")?.[1];
          if (facilityId) {
            response = await fetch("/fhir/Location/" + facilityId);
            response = await response.json();
            this.form.supervisor.facility = response.name;
          }

          let gradeId = supervisorPos.extension
            ?.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/salary-grade"
              );
            })
            ?.valueReference?.reference?.split("/")[1];
          if (gradeId) {
            response = await fetch("/fhir/Basic/" + gradeId);
            response = await response.json();
            this.form.supervisor.grade = response?.extension?.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
              );
            })?.valueString;
          }

          if (supervisorPract?.name?.length) {
            let nameObj = supervisorPract.name[0];
            let given = nameObj.given ? nameObj.given.join(" ") : "";
            let family = nameObj.family || "";
            this.form.supervisor.display = (given + " " + family).trim();
          }
          if (supRef) {
            this.form.supervisor.reference = supRef.reference;
          }
          // end of supervisor data
        }

        const isDepartmentalDirector = this.getExt(
          role,
          EXT.IS_DEPARTMENTAL_DIRECTOR,
          "valueCoding",
        );
        if (isDepartmentalDirector) {
          this.form.isDepartmentalDirector = isDepartmentalDirector;
        }

        const isHod = this.getExt(role, EXT.IS_HOD, "valueCoding");
        if (isHod) {
          this.form.isHeadOfDepartment = isHod;
          if (isHod.code === "yes") {
            // Read hod-details BEFORE loadHodTree — it guards on form.hodType being set
            const hodDetailsExt = role.extension?.find(
              (e) => e.url === EXT.HOD_DETAILS,
            );
            let savedLocRef = null;
            if (hodDetailsExt) {
              const typeExt = hodDetailsExt.extension?.find(
                (e) => e.url === "type",
              );
              const locExt = hodDetailsExt.extension?.find(
                (e) => e.url === "location",
              );
              this.form.hodType = typeExt?.valueString || null;
              savedLocRef = locExt?.valueReference?.reference || null;
            }

            // Now safe to load — form.hodType is set
            await this.loadHodTree();

            // Restore the saved selection
            if (savedLocRef) {
              if (this.form.hodType === "district") {
                // District nodes are already in the tree and treeLookup
                this.hodTree.active = [savedLocRef];
                // watcher fires → sets hodTree.displayValue
              } else {
                // Facility mode: facility not yet in the tree (lazy-loaded).
                // Fetch its name so the watcher can build the display label.
                try {
                  const locRes = await fetch(`/fhir/${savedLocRef}`);
                  const locData = await locRes.json();
                  this.hodTree.treeLookup[savedLocRef] = {
                    name: locData.name || savedLocRef,
                    type: "facility",
                  };
                } catch (_) {
                  this.hodTree.treeLookup[savedLocRef] = {
                    name: savedLocRef,
                    type: "facility",
                  };
                }
                this.hodTree.active = [savedLocRef];
              }
            }
          }
        }

        // Load salary
        await this.loadExistingSalary();
      } catch (err) {
        console.error("loadExistingRole error", err);
      }
    },

    async loadExistingSalary() {
      try {
        const res = await fetch(
          `/fhir/Basic?_profile=${SALARY_PROFILE}&practitionerrole=PractitionerRole/${this.queries.role}&_sort=-_lastUpdated&_count=1`,
        );
        const data = await res.json();
        if (!data.entry?.length) return;

        const sal = data.entry[0].resource;
        this.existingSalaryId = sal.id;

        const notchRef = this.getExt(sal, EXT.SALARY_NOTCH, "valueReference");
        if (notchRef) {
          const notchId = notchRef.reference; // 'Basic/xxx'

          // Fetch the notch resource to read its coding, amount and grade
          try {
            const notchRes = await fetch(`/fhir/${notchId}`);
            const notchData = await notchRes.json();

            const notchCoding = this.getExt(
              notchData,
              EXT.NOTCH,
              "valueCoding",
            );
            const amountExt = notchData.extension?.find(
              (x) => x.url === EXT.SALARY_AMOUNT,
            );
            const money = amountExt?.valueMoney;
            const amount = money
              ? `${money.currency} ${Number(money.value).toLocaleString()}`
              : "";
            const notchName = notchCoding
              ? notchCoding.display || notchCoding.code
              : notchId;

            const gradeRef = this.getExt(
              notchData,
              EXT.SALARY_GRADE_REF,
              "valueReference",
            );
            let gradeDisplay = gradeRef?.display || "";
            if (gradeRef?.reference && !gradeDisplay) {
              try {
                const gradeRes = await fetch(`/fhir/${gradeRef.reference}`);
                const gradeData = await gradeRes.json();
                gradeDisplay =
                  this.getExt(gradeData, EXT.POS_NAME, "valueString") ||
                  gradeRef.reference;
              } catch (err) {
                console.log(err);
              }
            }

            // Populate treeLookup so the active watcher resolves the display correctly
            this.salaryTree.treeLookup[notchId] = {
              name: notchName,
              gradeDisplay,
              amount,
              type: "notch",
            };

            // Setting active triggers the watcher which sets form.salaryNotch + displayValue
            this.salaryTree.active = [notchId];

            // Pre-open the parent grade in the tree so the user sees it highlighted
            if (gradeRef?.reference) {
              this.salaryTree.open = [gradeRef.reference];
            }
          } catch (_) {
            // Fallback: at minimum store the raw reference
            this.form.salaryNotch = {
              reference: notchId,
              display: notchRef.display || notchId,
            };
            this.salaryTree.displayValue = notchRef.display || notchId;
          }
        }

        this.form.salaryStartDate =
          this.getExt(sal, EXT.SALARY_START, "valueDate") || null;
      } catch (err) {
        console.error("loadExistingSalary error", err);
      }
    },

    // ── Submit ─────────────────────────────────────────────────────────
    async submit() {
      const valid = this.$refs.form.validate();
      let roleId = this.queries.role;
      let existingSalaryId = this.existingSalaryId;
      if (this.isPromotion) {
        roleId = null;
        existingSalaryId = null;
      }

      this.formSubmitted = true;
      if (!valid) return;

      if (
        this.isPromotion &&
        this.currentRole.positionReference &&
        this.form.position.reference === this.currentRole.positionReference
      ) {
        this.$store.commit("setMessage", {
          type: "error",
          text: "The new position must be different from the current position.",
        });
        return;
      }

      this.saving = true;
      try {
        if (this.isTermination) {
          this.fhir.termination = this.buildTermination();
          this.url = "http://ihris.org/fhir/Questionnaire/terminate-position";
        } else {
          this.fhir = {
            isPromotion: this.isPromotion,
            role: roleId,
            position: this.form.position.reference,
            startDate: this.form.startDate,
            endDate: this.isPermanent ? null : this.form.endDate || null,
            employmentCategory: this.form.employmentCategory,
            offerType: this.form.offerType,
            supervisor: this.form.supervisor.reference,
            isHeadOfDepartment: this.form.isHeadOfDepartment || null,
            isDepartmentalDirector: this.form.isDepartmentalDirector || null,
            hodType: this.form.hodType || null,
            hodDistrictId:
              this.form.hodType === "district" && this.hodTree.active.length
                ? this.hodTree.active[0]
                : null,
            hodFacilityId:
              this.form.hodType === "facility" && this.hodTree.active.length
                ? this.hodTree.active[0]
                : null,
            salaryNotch: this.form.salaryNotch?.reference || null,
            salaryStartDate: this.form.salaryStartDate || null,
            existingSalaryId: existingSalaryId,
          };
        }
        if (roleId) {
          this.afterSaveMessage = "Position updated successfully";
        } else if (this.isPromotion) {
          this.afterSaveMessage = "Promotion recorded successfully";
        } else {
          this.afterSaveMessage = "Position assigned successfully";
        }
        await this.processFHIR();
        if (this.isTermination) {
          this.$router.push(
            `/resource/view/practitioner/${this.queries.practitioner}`,
          );
        } else {
          this.$router.push(
            `/resource/view/practitioner/${this.queries.practitioner}`,
          );
        }
      } catch (err) {
        console.error("submit error", err);
      } finally {
        this.saving = false;
      }
    },

    // ── Termination submit ─────────────────────────────────────────────
    buildTermination() {
      // 2. Build departure Basic resource
      const extensions = [
        {
          url: EXT.DEPARTURE_DATE,
          valueDate: this.departure.lastWorkingDate,
        },
        {
          url: EXT.DEPARTURE_REASON,
          valueCoding: this.departure.reason,
        },
      ];

      if (this.showDismissalField && this.departure.dismissalReason) {
        extensions.push({
          url: EXT.DISMISSAL_REASON,
          valueString: this.departure.dismissalReason,
        });
      }

      if (
        this.showResignationDetails &&
        this.departure.resignationReasons.length
      ) {
        const subExts = this.departure.resignationReasons.map((r) => ({
          url: "resignation-reason",
          valueCoding: r,
        }));
        if (
          this.showResignationOther &&
          this.departure.resignationReasonOther
        ) {
          subExts.push({
            url: "resignation-reason-other",
            valueString: this.departure.resignationReasonOther,
          });
        }
        extensions.push({ url: EXT.RESIGNATION_DETAILS, extension: subExts });
      }

      if (
        this.showTransferOutDetails &&
        this.departure.transferToFacility.reference
      ) {
        extensions.push({
          url: EXT.TRANSFER_OUT_DETAILS,
          extension: [
            {
              url: "facility",
              valueReference: {
                reference: this.departure.transferToFacility.reference,
              },
            },
          ],
        });
      }

      // Links this departure record to the role it ends - RoleDepartureProfile's
      // practitioner-role-reference (1..1 MS). Was previously pointing at
      // "ihris-practitioner-role", which is the PractitionerRole *profile*
      // URL (used as meta.profile on PractitionerRole resources, see
      // assignPosition.js), not an extension - so this record never
      // actually carried its required role link.
      extensions.push({
        url: EXT.PRACTITIONER_ROLE_REFERENCE,
        valueReference: {
          reference: `PractitionerRole/${this.queries.role}`,
        },
      });

      const body = {
        resourceType: "Basic",
        meta: { profile: [DEPARTURE_PROFILE] },
        extension: extensions,
      };
      return body;
    },

    // ── Set Position (first-ever appointment) ───────────────────────────
    // "Set Position" is only reachable when this staff member has no role
    // record at all (matches the FSH action condition,
    // PractitionerRole.id.empty(), gating the link that leads here). A
    // staff member with any role - even a since-ended one - already used
    // this once and should go through Change Position instead.
    async checkNoExistingRole() {
      try {
        const res = await fetch(
          `/site/general/getCurrentRole/${this.queries.practitioner}`,
        );
        const role = await res.json();
        if (role && role.id) {
          this.loadError =
            "This staff member already has a position on record. Use Change Position instead.";
        }
      } catch (_) {
        // No role found (or the lookup failed) - proceed; the backend
        // re-checks this on submit regardless.
      }
    },

    // ── Load current role for read-only display (promotion / termination) ─
    async loadCurrentRole() {
      try {
        const res = await fetch(
          `/site/general/getCurrentRole/${this.queries.practitioner}`,
        );
        let role = await res.json();
        // Both Change Position and Record Termination act on the staff
        // member's *current* position - there's nothing to change or end
        // once the latest role has already ended. active is the real
        // signal for that, not period.end: a role can be inactive with no
        // end date set, and this must match what the backend itself checks
        // so the UI never shows a form the API will then refuse.
        if (!role || role.active !== true) {
          this.loadError = this.isTermination
            ? "This staff member has no active position to terminate."
            : "This staff member has no active position to change.";
          return;
        }

        const empCat = this.getExt(role, EXT.EMP_CAT, "valueCoding");
        this.currentRole.employmentCategory =
          empCat?.display || empCat?.code || "";
        this.currentRole.startDate = role.period?.start || null;
        this.currentRole.endDate = role.period?.end || null;

        // HOD
        const hodCoding = this.getExt(role, EXT.IS_HOD, "valueCoding");
        this.currentRole.isHOD = hodCoding?.code === "yes";
        if (this.currentRole.isHOD) {
          const hodDetailsExt = role.extension?.find(
            (e) => e.url === EXT.HOD_DETAILS,
          );
          const typeExt = hodDetailsExt?.extension?.find(
            (e) => e.url === "type",
          );
          this.currentRole.hodType = typeExt?.valueString || "";
        }

        // Departmental Director
        const departmentalDirectorCoding = this.getExt(
          role,
          EXT.IS_DEPARTMENTAL_DIRECTOR,
          "valueCoding",
        );
        this.currentRole.isDepartmentalDirector =
          departmentalDirectorCoding?.code === "yes";

        // Facility from role.location[0]
        const facilityRef = role.location?.[0]?.reference;
        if (facilityRef) {
          try {
            const fRes = await fetch(`/fhir/${facilityRef}`);
            const fData = await fRes.json();
            this.currentRole.facility = fData.name || facilityRef;
          } catch (_) {
            this.currentRole.facility = facilityRef;
          }
        }

        // Position Basic → designation + department
        const posRef = this.getExt(role, EXT.POSITION, "valueReference");
        this.currentRole.positionReference = posRef?.reference || null;
        if (posRef?.reference) {
          try {
            const posId = posRef.reference.split("/")[1];
            const posRes = await fetch(`/fhir/Basic/${posId}`);
            const posData = await posRes.json();
            // designation via designation extension → another Basic
            const desigRef = posData.extension?.find(
              (e) =>
                e.url ===
                "http://ihris.org/fhir/StructureDefinition/designation",
            )?.valueReference;
            if (desigRef?.reference) {
              try {
                const dId = desigRef.reference.split("/")[1];
                const dRes = await fetch(`/fhir/Basic/${dId}`);
                const dData = await dRes.json();
                this.currentRole.designation =
                  this.getExt(dData, EXT.POS_NAME, "valueString") ||
                  desigRef.display ||
                  "";
              } catch (_) {
                this.currentRole.designation = desigRef.display || "";
              }
            }
            const deptCoding = posData.extension?.find(
              (e) =>
                e.url ===
                "http://ihris.org/fhir/StructureDefinition/department",
            )?.valueCoding;
            this.currentRole.department =
              deptCoding?.display || deptCoding?.code || "";
          } catch (err) {
            console.log(err);
          }
        }

        // Supervisor name
        const supRef = this.getExt(role, EXT.SUPERVISOR, "valueReference");
        if (supRef?.reference) {
          try {
            const supId = supRef.reference.split("/")[1];
            const supRes = await fetch(`/fhir/Practitioner/${supId}`);
            const supData = await supRes.json();
            if (supData.name?.length) {
              const n = supData.name[0];
              const given = (n.given || []).join(" ");
              const family = n.family || "";
              this.currentRole.supervisor = (given + " " + family).trim();
            }
          } catch (err) {
            console.log(err);
          }
        }
      } catch (err) {
        console.error("loadCurrentRole error", err);
      }
    },

    // ── Departure ValueSets ────────────────────────────────────────────
    async loadDepartureValueSets() {
      const [depReason, resignReason] = await Promise.all([
        this.$fhirutils.expand(VS.DEPARTURE_REASON),
        this.$fhirutils.expand(VS.RESIGNATION),
      ]);
      this.departureReasonOptions = this.parseExpansion(depReason);
      this.resignationReasonOptions = this.parseExpansion(resignReason);
    },

    // ── Transfer-out location tree (for departure) ─────────────────────
    async loadDepartureTransferTree() {
      if (this.departureTransferTree.items.length) return;
      this.departureTransferTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => ({
          id: "Location/" + e.resource.id,
          name: e.resource.name,
          children: [],
        }));
        nodes.forEach((n) => {
          this.departureTransferTree.treeLookup[n.id] = {
            name: n.name,
            type: "district",
          };
        });
        this.departureTransferTree.items = nodes;
      } catch (err) {
        console.error("loadDepartureTransferTree error", err);
      } finally {
        this.departureTransferTree.loading = false;
      }
    },

    fetchDepartureTransferChildren(item) {
      const parentInfo = this.departureTransferTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      return fetch(`/fhir/Location?partof=${item.id}&_count=200`)
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const node = {
              id: "Location/" + e.resource.id,
              name: e.resource.name,
            };
            if (childType === "council") node.children = [];
            this.departureTransferTree.treeLookup[node.id] = {
              name: node.name,
              type: childType,
            };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) =>
          console.error("fetchDepartureTransferChildren error", err),
        );
    },

    clearDepartureTransferTree() {
      this.departureTransferTree.active = [];
      this.departureTransferTree.open = [];
      this.departureTransferTree.displayValue = "";
      this.departure.transferToFacility = { reference: null, display: "" };
    },

    onDepartureTransferTreeActiveChange(val) {
      const id = val && val.length ? val[0] : null;
      if (!id) {
        this.departureTransferTree.displayValue = "";
        this.departure.transferToFacility = { reference: null, display: "" };
        return;
      }
      const info = this.departureTransferTree.treeLookup[id];
      if (info?.type !== "facility") return;
      const name = info.name || id;
      this.departureTransferTree.displayValue = name;
      this.departure.transferToFacility = { reference: id, display: name };
      this.departureTransferTreeOpen = false;
    },

    // ── Helpers ────────────────────────────────────────────────────────
    getExt(resource, url, type) {
      const ext = resource?.extension?.find((e) => e.url === url);
      return ext ? ext[type] : null;
    },

    getInitials(name = "") {
      return name
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((w) => w[0].toUpperCase())
        .join("");
    },
  },
};
</script>

