const querystring = require("querystring");
export default {
  data: function() {
    return {
      isSaveInProgress: false,
      advancedValid: true,
    };
  },
  methods: {
    processFHIR: async function() {
      this.isSaveInProgress = true;
      this.advancedValid = true;
      this.loading = true;
      let editingResources = [];
      if (this.fhirId) {
        editingResources.push({
          profile: this.profile,
          id: this.fhirId,
        });
      }

      const mergeArrayExtensionFields = (children) => {
        let merged = [];
        for (let child of children) {
          for (let child1 of child.$children) {
            if (child1.isExtension) {
              for (let child2 of child1.$children) {
                merged.push(child2);
              }
            }
          }
        }
        return merged;
      };

      const processChildren = async (obj, children, itemMap) => {
        if (!itemMap) itemMap = {};

        for (let child of children) {
          let next = obj;
          let myItemMap = {};
          if (child.isArray) {
            //console.log("ARRAY", child.path)
          } else if (child.isQuestionnaireGroup) {
            if (child.resourceId) {
              editingResources.push({
                profile: child.profile,
                id: child.resourceId,
              });
            }
            //console.log("GROUP", child.path)
            let section = { linkId: child.path, text: child.label, item: [] };
            next.push(section);
            next = section.item;
          } else if (child.qField) {
            let item;
            if (itemMap.hasOwnProperty(child.path)) {
              item = itemMap[child.path];
            } else {
              item = { linkId: child.path, answer: [] };
              itemMap[child.path] = item;
              next.push(item);
            }
            let answer = {};
            answer[child.qField] = child.value;
            item.answer.push(answer);
            if (child.constraints) {
              child.errors = [];
              try {
                this.advancedValid =
                  this.advancedValid &&
                  (await this.$fhirutils.checkConstraints(
                    child.constraints,
                    this.constraints,
                    child.value,
                    child.errors,
                  ));
              } catch (err) {
                this.advancedValid = false;
                child.errors.push("An unknown error occurred.");
                console.log(err);
              }
            }
          }

          if (child.$children) {
            // console.log("PROCESSING CHILDREN OF",child.path)
            try {
              let children = [];
              if (child.isArray) {
                let merged = mergeArrayExtensionFields(child.$children);
                if (merged.length > 0) {
                  children = merged;
                }
              }
              if (children.length === 0) {
                children = child.$children;
              }
              await processChildren(next, children, myItemMap);
            } catch (err) {
              this.advancedValid = false;
              console.log(err);
            }
          }
          if (child.isQuestionnaireGroup && child.constraints) {
            child.errors = [];
            try {
              this.advancedValid =
                this.advancedValid &&
                (await this.$fhirutils.checkConstraints(
                  child.constraints,
                  this.constraints,
                  next,
                  child.errors,
                ));
            } catch (err) {
              this.advancedValid = false;
              child.errors.push("An unknown error occurred.");
              console.log(err);
            }
          }
        }
      };
      this.fhir.resourceType = "QuestionnaireResponse";
      this.fhir.questionnaire = this.url;
      this.fhir.status = "completed";
      this.fhir.item = [];
      try {
        await processChildren(this.fhir.item, this.$children);
      } catch (err) {
        this.advancedValid = false;
        console.log(err);
      }
      if (!this.advancedValid) {
        this.loading = false;
        this.$store.commit("setMessage", {
          type: "error",
          text: "There were errors on the form.",
        });
        this.isSaveInProgress = false;
        return;
      }
      this.$route.query.editing = false;
      if (editingResources.length > 0) {
        this.$route.query.editingResources = JSON.stringify(editingResources);
        this.$route.query.editing = true;
      }
      try {
        this.isSaveInProgress = true;
        this.loading = true;
        const response = await fetch(
          "/fhir/QuestionnaireResponse?" +
            querystring.stringify(this.$route.query),
          {
            method: "POST",
            headers: {
              "Content-Type": "application/fhir+json",
            },
            redirect: "manual",
            body: JSON.stringify(this.fhir),
          },
        );

        this.isSaveInProgress = false;

        if (response.status === 201) {
          const data = await response.json();
          this.loading = false;

          let subject;
          let viewPageId;
          if (data.meta.tag) {
            const redirect = data.meta.tag.find(
              (tag) => tag.system === "http://ihris.org/fhir/tags/resource",
            );
            if (redirect && redirect.code) {
              subject = redirect.code;
            }
          }
          if (!subject && data.subject && data.subject.reference) {
            subject = data.subject.reference;
          }
          if (subject) {
            let id;
            viewPageId = subject.split("/");
            if (viewPageId[1]) {
              id = viewPageId[1];
            } else {
              id = subject;
            }
            if (this.viewPage) {
              this.$router.push({
                name: "resource_view",
                params: { page: this.viewPage, id: id },
              });
            }
          } else if (this.fhirId && this.viewPage) {
            this.$router.push({
              name: "resource_view",
              params: { page: this.viewPage, id: this.fhirId },
            });
          }

          this.$store.commit("setMessage", {
            type: "success",
            text:
              this.afterSaveMessage ||
              this.$t("App.hardcoded-texts.Added successfully"),
          });

          return data;
        } else {
          this.loading = false;

          try {
            const data = await response.json();
            let errors;

            if (data.resourceType == "OperationOutcome") {
              try {
                errors = Array.from(
                  new Set(data.issue.map((issue) => issue.diagnostics)),
                ).join(", ");
              } catch (err) {
                console.log("Unable to retrieve errors from ", data);
                errors = "Unknown error format";
              }
            } else if (data.message) {
              errors = data.message;
            } else {
              errors = "Unknown error";
            }

            this.$store.commit("setMessage", {
              type: "error",
              text: "Error: " + errors,
            });

            throw new Error(errors);
          } catch (parseError) {
            throw new Error(parseError.message);
          }
        }
      } catch (error) {
        this.isSaveInProgress = false;
        this.loading = false;

        console.error("ProcessFHIR error:", error);
        if (
          !this.$store.state.message ||
          this.$store.state.message.type !== "error"
        ) {
          this.$store.commit("setMessage", {
            type: "error",
            text: "Failed to update data.",
          });
        }

        throw error;
      }
    },
  },
};
